'use strict';
const assert=require('node:assert/strict');
require('../src/pkl-image-binding.js');require('../src/colour-reduction.js');require('../src/colour-reduction-original.js');
const previous=globalThis.ATLAS_COLOUR_REDUCTION;
require('../src/colour-reduction-region.js');const R=globalThis.ATLAS_COLOUR_REDUCTION;
const colors=[{id:1,ref:'G',rgb:[55,121,26]},{id:2,ref:'R',rgb:[204,97,90]},{id:3,ref:'W',rgb:[238,228,208]}],master='8'.repeat(64);
const rgba=Uint8Array.from([61,123,25,255,61,123,26,128,55,121,26,255,61,123,25,255, 7,8,9,0,204,97,90,255,238,228,208,255,61,123,26,255]);
const args={rgba,width:4,height:2,colors,master,k:5},before=rgba.slice(),snapshot=JSON.stringify(colors);
assert.deepEqual(R.reduce(args),previous.reduce(args),'no rectangle legacy parity');
assert.deepEqual(R.reduce({...args,originalRgbs:[[61,123,25]]}),previous.reduce({...args,originalRgbs:[[61,123,25]]}),'global original parity');
const rects=[[0,0,1,1]],r=R.reduce({...args,protectedRectangles:rects});
for(const p of [0,1,4,5])assert.deepEqual(r.pixels.slice(p*4,p*4+4),rgba.slice(p*4,p*4+4),'rectangle exact RGBA including hidden RGB');
assert.notDeepEqual(r.pixels.slice(12,15),rgba.slice(12,15),'same RGB outside is still reducible');
assert.deepEqual([...r.protectionMask],[1,1,0,0,1,1,0,0]);assert.equal(r.report.rectangle_protection.protected_pixels,4);assert.equal(r.report.rectangle_protection.protected_transparent_pixels,1);
assert.equal(r.assignments[0],1);assert.equal(r.assignments[1],1);assert.equal(r.assignments[4],65535);
assert.deepEqual(R.reduce({...args,protectedRectangles:rects}),r,'determinism');
assert.deepEqual(R.reduce({...args,protectedRectangles:[...rects,...rects]}).pixels,r.pixels,'overlap is a union');
assert.deepEqual(rgba,before);assert.equal(JSON.stringify(colors),snapshot);assert.deepEqual(rects,[[0,0,1,1]]);
assert.throws(()=>R.reduce({...args,k:2,protectedRectangles:rects}),/exceed/);
assert.throws(()=>R.reduce({...args,protectedRectangles:[[0,0,4,1]]}),/bounds/);
assert.throws(()=>R.reduce({...args,protectedRectangles:[[1,1,0,0]]}),/bounds/);
assert.throws(()=>R.reduce({...args,protectedRectangles:[[0.5,0,1,1]]}),/bounds/);
assert.throws(()=>R.reduce({...args,protectedRectangles:null}),/bounds/);
assert.throws(()=>R.reduce({...args,protectedRectangles:Array(65).fill([0,0,0,0])}),/bounds/);
const edge=R.reduce({...args,k:2,protectedRectangles:[[3,1,3,1]]});assert.deepEqual(edge.pixels.slice(28,32),rgba.slice(28,32));assert.equal(edge.report.rectangle_protection.protected_pixels,1);
const transparent=R.reduce({...args,k:1,protectedRectangles:[[0,1,0,1]]});assert.equal(transparent.report.rectangle_protection.unique_visible_protected_rgb,0);assert.deepEqual(transparent.pixels.slice(16,20),rgba.slice(16,20));
const all=R.reduce({...args,k:6,protectedRectangles:[[0,0,3,1]]});assert.deepEqual(all.pixels,rgba);assert.equal(all.report.selected_references,0);
const both=R.reduce({...args,k:5,protectedRectangles:[[0,0,0,0]],originalRgbs:[[61,123,26]]});assert.deepEqual([...both.protectionMask],[1,1,0,0,0,0,0,1]);assert.deepEqual(both.pixels.slice(28,32),rgba.slice(28,32));
// One selected region with more than256 RGB values must fail, without mutation.
const many=Uint8Array.from(Array.from({length:257},(_,i)=>[i%256,i>>8,30,255]).flat());
assert.throws(()=>R.reduce({rgba:many,width:257,height:1,colors,master,k:256,protectedRectangles:[[0,0,256,0]]}),/exceed/);
console.log('PASS rectangle RGBA, hidden RGB, outside scope, overlap, endpoints, transparent-only, all-protected, limits, originals coexistence, no mutation and legacy parity');
